27	public class OneIntKeyGroupIdGenerator implements GroupIdGenerator {
28	  private final Int2IntOpenHashMap _groupIdMap;
29	  private final int _numGroupsLimit;
30	
31	  private int _numGroups = 0;
32	  private int _nullGroupId = INVALID_ID;
33	
34	  public OneIntKeyGroupIdGenerator(int numGroupsLimit) {
35	    _groupIdMap = new Int2IntOpenHashMap();
36	    _groupIdMap.defaultReturnValue(INVALID_ID);
37	    _numGroupsLimit = numGroupsLimit;
38	  }
39	
40	  @Override
41	  public int getGroupId(Object key) {
42	    if (_numGroups < _numGroupsLimit) {
43	      if (key == null) {
44	        if (_nullGroupId == INVALID_ID) {
45	          _nullGroupId = _numGroups++;
46	        }
47	        return _nullGroupId;
48	      }
49	      int groupId = _groupIdMap.computeIfAbsent((int) key, k -> _numGroups);
50	      if (groupId == _numGroups) {
51	        _numGroups++;
52	      }
53	      return groupId;
54	    } else {
55	      if (key == null) {
56	        return _nullGroupId;
57	      }
58	      return _groupIdMap.get((int) key);
59	    }
60	  }
61	
62	  @Override
63	  public int getNumGroups() {
64	    return _numGroups;
65	  }
66	
67	  @Override
68	  public Iterator<GroupKey> getGroupKeyIterator(int numColumns) {
69	    return new Iterator<GroupKey>() {
70	      final ObjectIterator<Int2IntMap.Entry> _entryIterator = _groupIdMap.int2IntEntrySet().fastIterator();
71	      boolean _returnNull = _nullGroupId != INVALID_ID;
72	
73	      @Override
74	      public boolean hasNext() {
75	        return _returnNull || _entryIterator.hasNext();
76	      }
77	
78	      @Override
79	      public GroupKey next() {
80	        Object[] row = new Object[numColumns];
81	        if (_returnNull) {
82	          _returnNull = false;
83	          return new GroupKey(_nullGroupId, row);
84	        }
85	        Int2IntMap.Entry entry = _entryIterator.next();
86	        row[0] = entry.getIntKey();
87	        return new GroupKey(entry.getIntValue(), row);
88	      }
89	    };
