75	  @VisibleForTesting
76	  static final ThreadLocal<Long2IntOpenHashMap> THREAD_LOCAL_LONG_MAP = ThreadLocal.withInitial(() -> {
77	    Long2IntOpenHashMap map = new Long2IntOpenHashMap(INITIAL_MAP_SIZE);
78	    map.defaultReturnValue(INVALID_ID);
79	    return map;
80	  });
81	  @VisibleForTesting
82	  static final ThreadLocal<Object2IntOpenHashMap<IntArray>> THREAD_LOCAL_INT_ARRAY_MAP = ThreadLocal.withInitial(() -> {
83	    Object2IntOpenHashMap<IntArray> map = new Object2IntOpenHashMap<>(INITIAL_MAP_SIZE);
84	    map.defaultReturnValue(INVALID_ID);
85	    return map;
86	  });
