94	  // The first dimension is the index of group-by column
95	  // Reusable buffer for single-value column dictionary ids
96	  private final int[][] _singleValueDictIds;
97	  // Reusable buffer for multi-value column dictionary ids
98	  private final int[][][] _multiValueDictIds;
