102	  private final int _globalGroupIdUpperBound;
103	  private final RawKeyHolder _rawKeyHolder;
104	
105	  public DictionaryBasedGroupKeyGenerator(BaseProjectOperator<?> projectOperator,
106	      ExpressionContext[] groupByExpressions, int numGroupsLimit, int arrayBasedThreshold,
107	      @Nullable Map<ExpressionContext, Integer> groupByExpressionSizesFromPredicates) {
108	    assert numGroupsLimit >= arrayBasedThreshold;
109	
110	    _groupByExpressions = groupByExpressions;
111	    _numGroupByExpressions = groupByExpressions.length;
112	
113	    _cardinalities = new int[_numGroupByExpressions];
114	    _isSingleValueColumn = new boolean[_numGroupByExpressions];
115	    _dictionaries = new Dictionary[_numGroupByExpressions];
116	    _singleValueDictIds = new int[_numGroupByExpressions][];
117	    _multiValueDictIds = new int[_numGroupByExpressions][][];
118	    // no need to intern dictionary values when there is only one group by expression because
119	    // only one call will be made to the dictionary to extract each raw value.
120	    _internedDictionaryValues = _numGroupByExpressions > 1 ? new Object[_numGroupByExpressions][] : null;
121	    Map<ExpressionContext, Integer> cardinalityMap = new HashMap<>(_numGroupByExpressions);
122	    long cardinalityProduct = 1L;
123	    boolean longOverflow = false;
124	    for (int i = 0; i < _numGroupByExpressions; i++) {
125	      ExpressionContext groupByExpression = groupByExpressions[i];
126	      ColumnContext columnContext = projectOperator.getResultColumnContext(groupByExpression);
127	      _dictionaries[i] = columnContext.getDictionary();
128	      assert _dictionaries[i] != null;
129	      int cardinality = _dictionaries[i].length();
130	      _cardinalities[i] = cardinality;
131	      cardinalityMap.put(groupByExpression, cardinality);
132	      if (_internedDictionaryValues != null && cardinality < MAX_DICTIONARY_INTERN_TABLE_SIZE) {
133	        _internedDictionaryValues[i] = new Object[cardinality];
134	      }
135	      if (!longOverflow) {
136	        if (cardinalityProduct > Long.MAX_VALUE / cardinality) {
137	          longOverflow = true;
138	        } else {
139	          cardinalityProduct *= cardinality;
140	        }
141	      }
142	      _isSingleValueColumn[i] = columnContext.isSingleValue();
143	    }
144	    if (groupByExpressionSizesFromPredicates != null) {
145	       Pair<Boolean, Long> optimizedCardinality = getOptimizedGroupByCardinality(groupByExpressionSizesFromPredicates,
146	           cardinalityMap);
